style.css:
@-moz-document domain("roblox.com") {
/* Set the background image for the entire page */
  html, body {
    background: url("https://i.imgur.com/8RnSP9Z.jpeg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Make main content containers semi-transparent with a blur effect */
  .container-main, .content, .navbar {
    background-color: rgba(255, 255, 255, 0.7) !important;
    backdrop-filter: blur(5px);
  }

  /* Style the navbar with a pink tinted background and border */
  .navbar {
    background-color: rgba(255, 105, 180, 0.8) !important; /* pink tint */
    border-bottom: 2px solid #ff69b4 !important;
  }

  /* Change link colors and text labels to pink and use a fun font */
  a, .text-label {
    color: #ff69b4 !important; /* pink links */
    font-family: 'Comic Sans MS', cursive, sans-serif !important;
  }
}
